arguments.command:
cd /app
python3 << 'PYEOF'
import csv, re, json
REQUIRED=["race","colour","religion","sex","familial status","national origin","disability","sexual orientation","veteran status","marital status","source of income"]
RESP={"closing_page","agent_bio"}
MARKER="this brokerage complies with the federal fair housing act"
rows=list(csv.DictReader(open("/app/input/seller_book_sections.csv")))
def notice(t):
    low=t.lower(); i=low.find(MARKER); return (None,t) if i==-1 else (t[i:],t[:i])
def named(n):
    if not n: return set()
    low=n.lower(); s=set()
    for c in REQUIRED:
        vs=[c] if c!="colour" else ["colour","color"]
        for v in vs:
            if re.search(r"\b"+re.escape(v)+r"\b", low): s.add(c); break
    return s
def pcl(t):
    low=t.lower()
    for t2 in ["race","colour","color","religion","sex","familial status","national origin","disability","sexual orientation","veteran status"]:
        if re.search(r"\b"+re.escape(t2)+r"\b", low): return True
    for t2 in ["church","churches","churchgoing","parish","faith","worship","congregation"]:
        if re.search(r"\b"+re.escape(t2)+r"\b", low): return True
    if re.search(r"\b(family-oriented|young families|churchgoing households|long-established families|congregation-centred)\b", low): return True
    if re.search(r"\b(street|block|neighbourhood|neighborhood)\b", low) and re.search(r"\b(households|families|family-oriented)\b", low): return True
    return False
def pn(t):
    low=t.lower()
    return any(re.search(p,low) for p in [r"write us a a letter",r"write us a letter",r"personal note about yourself",r"personal note about themselves",r"covering letter introducing yourself",r"introduce a short personal note",r"letter about what brought you here",r"tell us about yourselves",r"why this home suits them",r"like to know who is buying"])
expected={}
for r in rows:
    sid=r["section_id"]; role=r["role"]; body=r["body"]; title=r["title"]
    n,p=notice(body); nm=named(n)
    complete = n is not None and nm==set(REQUIRED); abridged = n is not None and not complete
    f=[]
    if pn(title+" "+body): f.append("PROHIBITED_PERSONAL_NARRATIVE")
    hit=pcl(p+" "+title)
    if abridged and pcl(n): hit=True
    if hit: f.append("PROTECTED_CLASS_LANGUAGE")
    if role in RESP and not complete: f.append("DISCLAIMER_MISSING")
    expected[sid]="|".join(f) if f else "none"
written={r["section_id"]:r["finding"] for r in csv.DictReader(open("/app/fairhousing_audit.csv"))}
mism=[(s,expected[s],written.get(s)) for s in expected if expected[s]!=written.get(s)]
order=[r["section_id"] for r in rows]
order_ok = list(written.keys())==order
print("inventory-order match:", order_ok)
print("findings match:", not mism)
if mism: print("MISMATCHES:", mism)
print("expected==written for all 30:", expected==written)
PYEOF

